import { z } from 'zod';
import type { ProductCategory } from './products.js';

export const TRY_ON_STATUSES = ['pending', 'processing', 'ready', 'failed', 'cancelled'] as const;
export type TryOnStatus = (typeof TRY_ON_STATUSES)[number];
export const ACTIVE_TRY_ON_STATUSES: readonly TryOnStatus[] = ['pending', 'processing'];

export const TRY_ON_DISCLAIMER =
  'Virtual try-on is an AI-generated visual preview. Appearance, drape and fit may differ from the physical garment.';
export const MOCK_TRY_ON_NOTICE =
  'Mock result — this preview was NOT generated by AI. It is a simple placeholder image used while no real try-on provider is connected.';

/** Body region a garment needs, and the provider-facing garment category. */
export const GARMENT_REGIONS = ['upper_body', 'lower_body', 'full_body'] as const;
export type GarmentRegion = (typeof GARMENT_REGIONS)[number];
export const GARMENT_REGION_LABELS: Record<GarmentRegion, string> = {
  upper_body: 'Upper-body garments',
  lower_body: 'Lower-body garments',
  full_body: 'Full-body garments (e.g. dresses)',
};

export const CATEGORY_REGION: Record<ProductCategory, GarmentRegion> = {
  tops: 'upper_body',
  shirts: 'upper_body',
  t_shirts: 'upper_body',
  jackets: 'upper_body',
  dresses: 'full_body',
  trousers: 'lower_body',
  jeans: 'lower_body',
  skirts: 'lower_body',
  shorts: 'lower_body',
};

export const MAX_TRY_ON_PHOTO_BYTES = 12 * 1024 * 1024;

/**
 * Where the person image of a try-on came from. `saved_photo`: a stored photo reused from an
 * earlier try-on; `uploaded_photo` / `camera_photo`: the photo's first use.
 */
export const PERSON_SOURCES = ['uploaded_photo', 'camera_photo', 'saved_photo', 'avatar_render'] as const;
export type PersonSource = (typeof PERSON_SOURCES)[number];
/** How a stored try-on photo was obtained. */
export const PHOTO_ORIGINS = ['uploaded_photo', 'camera_photo', 'avatar_render'] as const;
export type PhotoOrigin = (typeof PHOTO_ORIGINS)[number];

export const AVATAR_TRY_ON_NOTICE = 'Avatar try-on is an approximate visual preview based on your saved body measurements.';
export const AVATAR_TRY_ON_MISSING = 'You need to create your avatar before using avatar try-on.';

/** Framing of an avatar render: upper body (head to mid-thigh) or the whole body. */
export const AVATAR_RENDER_FRAMINGS = ['upper_body', 'full_body'] as const;
export type AvatarRenderFraming = (typeof AVATAR_RENDER_FRAMINGS)[number];
export const FRAMING_FOR_REGION: Record<GarmentRegion, AvatarRenderFraming> = {
  upper_body: 'upper_body',
  lower_body: 'full_body',
  full_body: 'full_body',
};

/** Renders (or reuses) a front image of the user's current avatar for this product's garment type. */
export const avatarRenderRequestSchema = z.object({ productId: z.uuid() });

/**
 * Pose-based suitability of a try-on photo. Computed in the browser with the same
 * on-device pose model as the body scan (the server checks file, size, orientation and blur).
 */
export const tryOnSuitabilitySchema = z.object({
  checkedBy: z.string().max(80),
  onePerson: z.boolean(),
  facingCamera: z.boolean(),
  /** Person height as a fraction of image height. */
  personHeightFraction: z.number().min(0).max(1),
  regions: z.object({ upper_body: z.boolean(), lower_body: z.boolean(), full_body: z.boolean() }),
  lightingOk: z.boolean(),
  sharpOk: z.boolean(),
  issues: z.array(z.string().max(200)).max(20),
});
export type TryOnSuitability = z.infer<typeof tryOnSuitabilitySchema>;

/** Server-side checks added when the photo is stored. */
export interface ServerPhotoChecks {
  width: number;
  height: number;
  sharpness: number;
  sharpOk: boolean;
}

export interface TryOnPhoto {
  id: string;
  source: PhotoOrigin;
  /** Set for avatar renders. */
  avatarId: string | null;
  avatarModelVersion: string | null;
  imageUrl: string;
  thumbnailUrl: string;
  suitability: TryOnSuitability & { server: ServerPhotoChecks };
  createdAt: string;
}

export const createTryOnSchema = z.object({
  productId: z.uuid(),
  personPhotoId: z.uuid(),
  /** Defaults to the product's selected try-on image. */
  productImageId: z.uuid().optional(),
  /** One per user action; repeating it returns the same job instead of paying twice. */
  idempotencyKey: z.uuid(),
  /** Required when the provider is an external service. */
  acknowledgeThirdParty: z.boolean().default(false),
});
export type CreateTryOnInput = z.input<typeof createTryOnSchema>;

export const TRY_ON_ERROR_CODES = [
  'unsupported_garment',
  'unsuitable_person_photo',
  'unsuitable_garment_image',
  'provider_timeout',
  'provider_moderation',
  'provider_rate_limited',
  'provider_unavailable',
  'generation_failed',
  'interrupted',
] as const;
export type TryOnErrorCode = (typeof TRY_ON_ERROR_CODES)[number];

/** User-facing messages; raw provider errors are only logged on the server. */
export const TRY_ON_ERROR_MESSAGES: Record<TryOnErrorCode, string> = {
  unsupported_garment: 'This type of garment isn’t supported for virtual try-on yet.',
  unsuitable_person_photo: 'Your photo isn’t suitable for this garment. Try a clearer, front-facing photo showing the needed part of your body.',
  unsuitable_garment_image: 'The garment image couldn’t be used. Choose a clearer, front-facing image of the garment.',
  provider_timeout: 'The try-on service took too long to respond. Please try again.',
  provider_moderation: 'The try-on service declined to process these images.',
  provider_rate_limited: 'The try-on service is busy right now. Please try again in a few minutes.',
  provider_unavailable: 'The try-on service is unavailable right now. Please try again later.',
  generation_failed: 'The try-on couldn’t be generated. Please try again.',
  interrupted: 'Generation was interrupted. Please try again.',
};

export interface TryOnProviderInfo {
  provider: string;
  modelVersion: string;
  source: 'mock' | 'real';
  /** Images are sent to a third-party service. */
  external: boolean;
  /** Manually tested end to end with real images. */
  verified: boolean;
  /**
   * Avatar renders as person input have been seen to work with this provider. False for the mock
   * and until a real model has been checked generating clothing on the avatar.
   */
  avatarVerified: boolean;
  disclosure: string | null;
  limits: { dailyLimit: number; usedToday: number; maxActive: number };
}

export interface TryOnResult {
  id: string;
  productId: string;
  productImageId: string;
  personPhotoId: string;
  personSource: PersonSource;
  /** Set when `personSource` is `avatar_render`. */
  avatarId: string | null;
  avatarModelVersion: string | null;
  status: TryOnStatus;
  source: 'mock' | 'real';
  provider: string;
  modelVersion: string;
  providerJobId: string | null;
  errorCode: TryOnErrorCode | null;
  errorMessage: string | null;
  resultImageUrl: string | null;
  personPhotoUrl: string | null;
  garmentImageUrl: string;
  productName: string;
  savedLookId: string | null;
  createdAt: string;
  startedAt: string | null;
  completedAt: string | null;
}

export interface TryOnResponse {
  tryOn: TryOnResult;
}
export interface TryOnListResponse {
  tryOns: TryOnResult[];
}
export interface TryOnPhotoListResponse {
  photos: TryOnPhoto[];
}
export interface TryOnPhotoResponse {
  photo: TryOnPhoto;
}

export interface SavedLook {
  id: string;
  productId: string;
  tryOnResultId: string;
  createdAt: string;
  tryOn: TryOnResult;
}
export interface SavedLookListResponse {
  looks: SavedLook[];
}
